/* BEGIN NEW WORKSHOP COVERS */
Object.assign(WORKSHOP_COVERS,{"write": "data:image/webp;base64,", "money": "data:image/webp;base64,", "detect": "data:image/webp;base64,"});
WORKSHOP_COVERS.bike='data:image/webp;base64,';
var photoWorkshopBefore=workshopArt;workshopArt=function(id){if(['write','money','detect','bike'].includes(id))return '<img class="work-cover" src="'+WORKSHOP_COVERS[id]+'" alt="" decoding="async" width="1000" height="563">';return photoWorkshopBefore(id)};
var photoPathBefore=vPath;vPath=function(){var h=photoPathBefore();if(!['write','money','detect'].includes(v.subj))return h;return h.replace('</div></div>','</div></div><div class="workshop-path-cover">'+workshopArt(v.subj)+'</div>')};
if(window.ShopLab)Object.assign(window.ShopLab,{WORKSHOP_COVERS:WORKSHOP_COVERS,workshopArt:workshopArt,vPath:vPath});
/* END NEW WORKSHOP COVERS */
